export function aplicarMiddlewares(req, middlewares) {
  throw new Error('não implementado');
}

testsCode:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { aplicarMiddlewares } from './solution.mjs';

const logMiddleware = (req) => ({ ...req, logado: true });
const jsonMiddleware = (req) => ({
  ...req,
  body: typeof req.body === 'string' ? JSON.parse(req.body) : req.body,
});

test('aplica os middlewares na ordem, passando o resultado adiante', () => {
  const resultado = aplicarMiddlewares({ body: '{"nome":"Ana"}' }, [logMiddleware, jsonMiddleware]);
  assert.deepEqual(resultado, { body: { nome: 'Ana' }, logado: true });
});

test('a ordem importa: quem toca por último no campo vence', () => {
  const primeiro = (req) => ({ ...req, passo: 1 });
  const segundo = (req) => ({ ...req, passo: 2 });
  assert.equal(aplicarMiddlewares({}, [primeiro, segundo]).passo, 2);
  assert.equal(aplicarMiddlewares({}, [segundo, primeiro]).passo, 1);
});

test('limite: sem middlewares, devolve o req sem mudanças', () => {
  assert.deepEqual(aplicarMiddlewares({ url: '/' }, []), { url: '/' });
});

test('middleware que não retorna o req lança erro', () => {
  assert.throws(() => aplicarMiddlewares({}, [() => undefined]), /retornou/);
});

solutionCode:
export function aplicarMiddlewares(req, middlewares) {
  if (!Array.isArray(middlewares)) {
    throw new Error('lista de middlewares inválida');
  }

  let atual = { ...req };
  for (const middleware of middlewares) {
    if (typeof middleware !== 'function') {
      throw new Error('middleware deve ser função');
    }
    const resultado = middleware(atual);
    if (resultado === undefined) {
      throw new Error('middleware não retornou o req');
    }
    atual = resultado;
  }
  return atual;
}
